INSERT INTO public.catalog_products (key, name, summary, problem, value, audiences, boundaries, entities, kpis, outcomes, status, source_provenance) VALUES (
  'product.content_factory', 'Content Factory', 'Produto de criação, transformação, governança, publicação e aprendizagem de conteúdo com fontes, Brand DNA, lineage e gates de qualidade.', 'Conteúdo disperso sem contexto reproduzível, rastreabilidade de fontes, revisão consistente ou vínculo confiável entre a versão publicada e seus resultados.', 'Transformar briefing e evidência em artefatos versionados, revisáveis, publicáveis e mensuráveis, preservando autoria, direitos, marca, aprovação e provenance.', '["tenant_content_editor", "tenant_content_reviewer", "tenant_marketing_manager", "agency_content_manager", "operator_quality_reviewer"]'::jsonb, '["não administra bookings", "não emite certificações", "não substitui ClientOps", "não publica sem policy e entitlement"]'::jsonb, '["ContentBrief", "SourceSet", "ContentArtifact", "ArtifactVersion", "MediaAsset", "Review", "Approval", "PublicationIntent", "PerformanceSnapshot"]'::jsonb, '["tempo até aprovação", "retrabalho por versão", "bloqueios de gate", "custo por artefato", "sucesso de publicação", "resultado por objetivo"]'::jsonb, '["Outcome verificável de Content Factory", "redução de retrabalho", "decisões explicáveis", "execução governada", "aprendizado acumulado"]'::jsonb, 'normative_target', '{"registry": "product-registry.json", "version": "0.9.0", "source_basis": {"derived_from": "v0.8.1 section 2", "expansion": "v0.9.0"}}'::jsonb)
ON CONFLICT (key) DO UPDATE SET name = EXCLUDED.name, summary = EXCLUDED.summary, problem = EXCLUDED.problem, value = EXCLUDED.value, audiences = EXCLUDED.audiences, boundaries = EXCLUDED.boundaries, entities = EXCLUDED.entities, kpis = EXCLUDED.kpis, outcomes = EXCLUDED.outcomes, status = EXCLUDED.status, source_provenance = EXCLUDED.source_provenance;

INSERT INTO public.catalog_products (key, name, summary, problem, value, audiences, boundaries, entities, kpis, outcomes, status, source_provenance) VALUES (
  'product.academy_ops', 'AcademyOps', 'Produto de competências, avaliações, evidências, trilhas, progresso, certificação e elegibilidade explicável.', 'Cursos isolados não demonstram competência, evidência ou elegibilidade, e decisões de aprendizagem carecem de versão, explicação e auditabilidade.', 'Conectar requisitos e competências a avaliações, evidências, intervenções e certificações com lifecycle verificável e proteção dos dados das pessoas.', '["learner", "instructor", "tenant_learning_admin", "assessor", "compliance_manager"]'::jsonb, '["curso não é unidade de verdade", "IA não decide sozinha sobre pessoas", "não administra agenda física", "não publica dados individuais"]'::jsonb, '["Competency", "Criterion", "Rubric", "Assessment", "Evidence", "LearningPath", "Enrollment", "Checkpoint", "Certification", "RecyclingPlan"]'::jsonb, '["conclusão", "validade de avaliação", "melhora pós-intervenção", "aderência", "reciclagem", "impacto operacional"]'::jsonb, '["Outcome verificável de AcademyOps", "redução de retrabalho", "decisões explicáveis", "execução governada", "aprendizado acumulado"]'::jsonb, 'normative_target', '{"registry": "product-registry.json", "version": "0.9.0", "source_basis": {"derived_from": "v0.8.1 section 2", "expansion": "v0.9.0"}}'::jsonb)
