INSERT INTO public.catalog_products (key, name, summary, problem, value, audiences, boundaries, entities, kpis, outcomes, status, source_provenance) VALUES (
  'product.schedule_ops', 'ScheduleOps', 'Produto de calendários, recursos, serviços, regras de disponibilidade, holds, bookings, presença e sincronização externa.', 'Agenda, capacidade, pessoas e recursos são geridos separadamente, causando conflito, double booking, erros de timezone e baixa rastreabilidade.', 'Calcular disponibilidade autorizada e transformar intenção em booking transacional, com hold, policy, eligibility, notificações e reconciliação.', '["scheduler", "service_provider", "resource_manager", "client_member", "public_requester"]'::jsonb, '["não distribui conteúdo", "não substitui AcademyOps", "não presume agenda externa sem reconciliation", "não expõe calendários privados"]'::jsonb, '["Calendar", "Resource", "Service", "AvailabilityRule", "TimeOff", "Slot", "Hold", "Booking", "EligibilityDecision", "CancellationPolicy"]'::jsonb, '["ocupação", "conflitos evitados", "no-show", "tempo até booking", "utilização", "freshness de sync"]'::jsonb, '["Outcome verificável de ScheduleOps", "redução de retrabalho", "decisões explicáveis", "execução governada", "aprendizado acumulado"]'::jsonb, 'normative_target', '{"registry": "product-registry.json", "version": "0.9.0", "source_basis": {"derived_from": "v0.8.1 section 2", "expansion": "v0.9.0"}}'::jsonb)
