INSERT INTO public.catalog_products (key, name, summary, problem, value, audiences, boundaries, entities, kpis, outcomes, status, source_provenance) VALUES (
  'product.reputation_ops', 'ReputationOps', 'Produto de ingestão de sinais, classificação, casos, respostas governadas, ações corretivas e análise de resultados reputacionais.', 'Sinais públicos chegam fragmentados, sem deduplicação, contexto, ownership ou ciclo controlado entre triagem, resposta e ação corretiva.', 'Converter sinais externos em casos priorizados, respostas revisadas e ações rastreáveis, distinguindo fato, hipótese, inferência e resultado.', '["reputation_analyst", "response_reviewer", "tenant_manager", "agency_manager", "operator_risk_reviewer"]'::jsonb, '["não publica automaticamente", "não trata correlação como causa", "não coleta fonte sem base e policy", "não altera registros de origem"]'::jsonb, '["ReputationSource", "ReputationSignal", "Classification", "TopicCluster", "ReputationCase", "ResponseDraft", "Investigation", "CorrectiveAction"]'::jsonb, '["tempo de triagem", "tempo de resposta", "recorrência", "resolução", "reabertura", "eficácia da ação"]'::jsonb, '["Outcome verificável de ReputationOps", "redução de retrabalho", "decisões explicáveis", "execução governada", "aprendizado acumulado"]'::jsonb, 'normative_target', '{"registry": "product-registry.json", "version": "0.9.0", "source_basis": {"derived_from": "v0.8.1 section 2", "expansion": "v0.9.0"}}'::jsonb)
