INSERT INTO public.catalog_products (key, name, summary, problem, value, audiences, boundaries, entities, kpis, outcomes, status, source_provenance) VALUES (
  'product.client_ops', 'ClientOps', 'Produto de perfil, consentimento, workspace, solicitações, SLA, jornada, documentos, comunicação e satisfação do cliente.', 'Relacionamento, documentos, solicitações e consentimentos ficam fragmentados, dificultando contexto compartilhado, SLA e experiência segura.', 'Oferecer workspace e timeline autorizados para clientes e equipes acompanharem informação, solicitações, resultados e satisfação sem virar CRM genérico.', '["client_member", "account_manager", "support_agent", "tenant_admin", "public_requester"]'::jsonb, '["não faz merge automático inseguro", "não substitui CRM externo", "não amplia acesso documental", "não usa segmentação opaca"]'::jsonb, '["CustomerProfile", "ContactPoint", "Consent", "Workspace", "JourneyEvent", "ClientRequest", "SLA", "Survey", "NPSResponse", "DocumentAccess"]'::jsonb, '["SLA", "resolução", "satisfação", "reabertura", "retenção", "conclusão", "precisão de matching"]'::jsonb, '["Outcome verificável de ClientOps", "redução de retrabalho", "decisões explicáveis", "execução governada", "aprendizado acumulado"]'::jsonb, 'normative_target', '{"registry": "product-registry.json", "version": "0.9.0", "source_basis": {"derived_from": "v0.8.1 section 2", "expansion": "v0.9.0"}}'::jsonb)
